import{_ as i,l as n,o as e,c as s,v as t,p as l,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"PGO","description":"","frontmatter":{"title":"PGO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pgo.md","filePath":"cs/pgo.md","lastUpdated":1789023840000}'),c={name:"cs/pgo.md"};function u(_,a,P,f,m,A){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="pgo" tabindex="-1">PGO <a class="header-anchor" href="#pgo" aria-label="Permalink to &quot;PGO&quot;">​</a></h1><div class="epigraph"><p>轮廓指导优化：用代表性运行的边计数、函数热度来选内联、展开、布局与推测。静态启发是没有轮廓时的退路。</p><footer>—— 据 Pettis and Hansen, Profile Guided Code Positioning；Chang, Mahlke and Hwu 内联；龙书 8.7 整理</footer></div><p>上一课<a href="/cs/natural-loops">自然循环</a>给出循环结构，但不知转几圈。缺口是<strong>动态频率</strong>：PGO（profile-guided optimization）。插桩或采样得边权重，第二次编译使用。本课钉工作流与偏差，不写 LTO 的全程序合并——下一课二者常一起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态：循环当「热」、调用当「一次」。错。PGO：<code>branch_weights</code>、函数 entry count。决策：热函数多内联、热循环多展开、热边落在 fall-through。缺口是<strong>把计数变成 IR 元数据</strong>，不是识别回边。</p><p>采样 PGO（AutoFDO）用 perf 映射回源/IR，插桩少，精度与符号相关。</p><h3 id="轮廓不是证明" tabindex="-1">轮廓不是证明 <a class="header-anchor" href="#轮廓不是证明" aria-label="Permalink to &quot;轮廓不是证明&quot;">​</a></h3><p>训练集偏则优化偏。必须仍可靠：不能因「从未走到」就删有副作用的路径，除非语言允许（有的语言对未定义的冷路径更激进——危险）。</p><p><span class="marginnote">Pettis–Hansen 1990 代码布局。Hwu 组的 IMPACT。LLVM/GCC <code>-fprofile-generate/use</code>。本课不把机器学习启发式当文献核心。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一代：插桩编译、跑负载、合并 <code>.profraw</code>。二代：读轮廓，标注 CFG 边，跑内联/展开/布局/推测（有的 JIT 用同一思想）。校验：源变了则轮廓失效，要降级。</p>',11)),(e(),l(h,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INST%5B%22%E6%8F%92%E6%A1%A9%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%20--%3E%20RUN%5B%22%E4%BB%A3%E8%A1%A8%E6%80%A7%E8%B4%9F%E8%BD%BD%22%5D%0A%20%20RUN%20--%3E%20PROF%5B%22%E8%BD%AE%E5%BB%93%E6%95%B0%E6%8D%AE%22%5D%0A%20%20PROF%20--%3E%20OPT%5B%22%E4%BA%8C%E6%AC%A1%E7%BC%96%E8%AF%91%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与值范围：PGO 可给常见值，用于推测（带检查）。失败路径仍正确。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>间接调用：轮廓给目标分布，去虚+内联。布局：把热块排在一起减 i-cache 与分支惩罚。不要用错误映射的采样去移动块。</p><p>多进程合并计数要原子或离线 sum。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 AutoFDO 流水线。后课默认：热度驱动启发，语义仍靠静态可靠。下一课 LTO：轮廓跨 TU 更有用。</p><p>也不把 PGO 当用户画像隐私课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PGO：运行计数指导内联、展开、布局、推测。</li><li>训练偏差会改性能，不应改可靠语义。</li><li>与循环树、调用图一起用。</li><li>出处：Pettis and Hansen；Chang/Mahlke/Hwu；龙书。</li></ul>',9))])}const B=i(c,[["render",u]]);export{g as __pageData,B as default};
